// Run with: npm run seed
// Wipes the database and adds an admin, a demo user, all movies from data/movies.js and shows for the next 5 days.
require("dotenv").config();
const mongoose = require("mongoose");
const bcrypt = require("bcryptjs");
const User = require("./models/User");
const Movie = require("./models/Movie");
const Show = require("./models/Show");
const Booking = require("./models/Booking");
const Favorite = require("./models/Favorite");
const Review = require("./models/Review");
const movieData = require("./data/movies");

// Posters are generated by scripts/generate-posters.js and served by the React app from /posters
const movies = movieData.map(({ slug, art, poster, ...rest }) => ({
  ...rest,
  poster: poster || `/posters/${slug}.svg`,
}));

const theatres = ["PVR Phoenix", "INOX City Centre", "Cinepolis Square", "Carnival Cinemas"];
const hours = [10, 13, 16, 19, 22];

(async () => {
  try {
    await mongoose.connect(process.env.MONGO_URI);
    await Promise.all([User.deleteMany(), Movie.deleteMany(), Show.deleteMany(), Booking.deleteMany(), Favorite.deleteMany(), Review.deleteMany()]);

    await User.create([
      { name: "Admin", email: "admin@imovies.com", password: await bcrypt.hash("admin123", 10), role: "admin" },
      { name: "Demo User", email: "user@imovies.com", password: await bcrypt.hash("user123", 10) },
    ]);

    const created = await Movie.insertMany(movies);

    const shows = [];
    created.forEach((movie, mi) => {
      for (let d = 0; d < 5; d++) {
        // three shows per movie per day, spread across theatres
        [0, 1, 2].forEach((k) => {
          const hour = hours[(mi + k + d) % hours.length];
          const start = new Date();
          start.setDate(start.getDate() + d);
          start.setHours(hour, 0, 0, 0);
          if (start < new Date()) return; // skip shows already in the past
          shows.push({
            movie: movie._id,
            theatre: theatres[(mi + k) % theatres.length],
            screen: `Screen ${k + 1}`,
            startTime: start,
            price: 150 + 50 * ((mi + k) % 3),
          });
        });
      }
    });
    await Show.insertMany(shows);

    console.log(`Seeded ${created.length} movies and ${shows.length} shows.`);
    console.log("Admin login: admin@imovies.com / admin123");
    console.log("User login:  user@imovies.com / user123");
  } catch (err) {
    console.error("Seed failed:", err.message);
    process.exitCode = 1;
  } finally {
    await mongoose.disconnect();
  }
})();
